public void run(ABSExcessObsoleteContract _contract)
{
    ABSExcessObsolete   toDelete;
    ABSExcessObsolete   eoTotal;
    InventSiteId        siteId      = _contract.parmSiteId();
    boolean             deleteRegen = _contract.parmDeleteAndRegenerate();
    InventSite          inventSite;
    real                totalProvision;

    if (deleteRegen)
    {
        try
        {
            ttsbegin;

            toDelete.skipDataMethods(true);
            toDelete.skipDeleteActions(true);
            toDelete.skipEvents(true);

            if (siteId)
                delete_from toDelete where toDelete.SiteId == siteId;
            else
                delete_from toDelete;

            ttscommit;
        }
        catch (Exception::Error)
        {
            error("@ABS:ABSEODeleteFailed");
            return;
        }
    }

    if (siteId)
    {
        ABSExcessObsoleteEngine::newParameters(siteId, _contract).run();
    }
    else
    {
        while select SiteId from inventSite
        {
            ABSExcessObsoleteEngine::newParameters(inventSite.SiteId, _contract).run();
        }
    }

    select sum(ProvisionValue) from eoTotal
        where (siteId == '' || eoTotal.SiteId == siteId);
    totalProvision = eoTotal.ProvisionValue;

    info(strFmt("@ABS:ABSEOCompleted",
        siteId ? siteId : "@ABS:ABSAllSites",
        totalProvision));
}
